+function backupCounts(backup) {
+  if (backup === null || typeof backup !== 'object' || Array.isArray(backup)) {
+    throw new Error('Il file deve contenere un backup JSON di Custode.');
+  }
+  if (backup.schemaVersion !== 1) throw new Error('Versione del backup non supportata: scegli un backup di Custode versione 1.');
+  const keys = ['schemaVersion', 'items', 'tasks', 'history'];
+  if (Object.keys(backup).some(key => !keys.includes(key)) ||
+      !['items', 'tasks', 'history'].every(key => Array.isArray(backup[key]) &&
+        backup[key].every(record => record !== null && typeof record === 'object' && !Array.isArray(record)))) {
+    throw new Error('Il backup deve contenere gli elenchi di oggetti, interventi e storico nel formato di Custode.');
+  }
+  return { items: backup.items.length, tasks: backup.tasks.length, history: backup.history.length };
+}
