+  element('backup-file-status').textContent = '';
+  element('backup-file-error').hidden = true;
+  element('backup-file-error').textContent = '';
+  element('backup-filename').textContent = '';
+  element('backup-file-summary').textContent = '';
+  element('backup-preview').hidden = true;
+  element('clear-backup-file').hidden = true;
+  updateBackupControls();
+}
+
+async function readBackupFile() {
+  const file = backupFile.files[0];
+  const sequence = ++backupFileSequence;
+  selectedBackup = null;
+  restoreBlocked = false;
+  readingBackup = Boolean(file);
+  backupFile.removeAttribute('aria-invalid');
+  backupFile.setAttribute('aria-busy', String(readingBackup));
+  element('backup-feedback').textContent = '';
+  element('backup-file-error').hidden = true;
+  element('backup-file-error').textContent = '';
+  element('backup-preview').hidden = true;
+  element('backup-file-status').textContent = file ? 'Lettura del file… Nessun dato viene modificato.' : '';
+  element('clear-backup-file').hidden = !file;
+  updateBackupControls();
+  if (!file) return;
+  try {
+    if (file.size > maxRestoreBytes) throw new Error('Il file supera 2 MiB. Il ripristino richiede una richiesta completa entro 2 MiB. Conserva il file e usa la copia della cartella dati a servizio fermo, come descritto nel README.');
+    let bytes;
+    try { bytes = await file.arrayBuffer(); }
+    catch { throw new Error('Impossibile leggere il file. Verifica che sia ancora disponibile e scegli una copia leggibile.'); }
+    if (sequence !== backupFileSequence) return;
+    let backup;
+    try { backup = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)); }
+    catch { throw new Error('Il file non contiene JSON valido in UTF-8. Scegli una copia integra del backup.'); }
+    const counts = backupCounts(backup);
+    const body = JSON.stringify({ backup, mode: 'replace' });
+    if (new Blob([body]).size > maxRestoreBytes) {
+      throw new Error('Il file entra in 2 MiB, ma la richiesta completa di ripristino supera il limite. Nessun dato è stato modificato. Usa la copia della cartella dati a servizio fermo, come descritto nel README.');
+    }
+    // Keep the prepared request unchanged through the confirmation step.
+    selectedBackup = { name: file.name, counts, body };
+    element('backup-filename').textContent = file.name;
+    element('backup-file-summary').textContent = `Oggetti: ${counts.items} · Interventi: ${counts.tasks} · Completamenti: ${counts.history}.`;
+    element('backup-preview').hidden = false;
+    element('backup-file-status').textContent = 'File letto. Nessun dato modificato. Prosegui per controllare il riepilogo e confermare.';
+  } catch (error) {
+    if (sequence !== backupFileSequence) return;
+    backupFile.setAttribute('aria-invalid', 'true');
+    element('backup-file-status').textContent = '';
+    element('backup-file-error').textContent = `${error.message} La lettura del file non ha modificato l’archivio.`;
+    element('backup-file-error').hidden = false;
+    if (currentView === 'backup' && document.activeElement === backupFile) element('backup-file-error').focus();
+  } finally {
+    if (sequence === backupFileSequence) {
+      readingBackup = false;
+      backupFile.setAttribute('aria-busy', 'false');
+      updateBackupControls();
+    }
+  }
+}
+
+async function downloadBackup() {
+  if (downloadingBackup) return;
+  downloadingBackup = true;
+  const button = element('download-backup');
+  const status = element('download-status');
+  button.disabled = true;
+  element('download-error').hidden = true;
+  status.textContent = 'Preparazione del backup completo…';
+  status.focus();
+  try {
+    const response = await fetch('/api/backup', { headers: { Accept: 'application/json' }, cache: 'no-store', signal: AbortSignal.timeout(10000) });
+    if (!response.ok) {
+      const error = await response.json();
+      throw new Error(typeof error?.error === 'string' ? error.error : 'Il servizio non ha prodotto il backup.');
+    }
+    const blob = await response.blob();
+    // Verify that an error page is not offered as a backup. Download the exact
+    // response bytes, without filtering, normalizing or serializing them again.
+    let backup;
+    try { backup = JSON.parse(await blob.text()); }
+    catch { throw new Error('Il servizio ha restituito un file non valido. Riprova il download.'); }
+    backupCounts(backup);
+    const exceedsRestoreLimit = new Blob([JSON.stringify({ backup, mode: 'replace' })]).size > maxRestoreBytes;
+    const url = URL.createObjectURL(blob);
+    const link = node('a');
+    const filename = `custode-backup-${browserToday()}.json`;
+    link.href = url;
+    link.download = filename;
+    document.body.append(link);
+    try { link.click(); }
+    finally {
+      link.remove();
+      setTimeout(() => URL.revokeObjectURL(url), 60000);
+    }
+    status.textContent = `Download avviato: ${filename}. Controlla i download del browser e conserva il file.`;
+    if (exceedsRestoreLimit) status.textContent += ' L’archivio supera il limite di ripristino via interfaccia: conserva anche una copia della cartella dati a servizio fermo (README).';
+  } catch (error) {
+    status.textContent = '';
+    element('download-error').textContent = `Backup non scaricato. ${error.name === 'TimeoutError' || error.name === 'TypeError' ? 'Controlla che Custode sia in esecuzione e riprova.' : error.message} Il download non modifica l’archivio.`;
+    element('download-error').hidden = false;
+    if (currentView === 'backup' && !anyDialogOpen() && document.activeElement === status) element('download-error').focus();
+  } finally {
+    downloadingBackup = false;
+    button.disabled = false;
+    if (currentView === 'backup' && !anyDialogOpen() && document.activeElement === status) button.focus();
+  }
+}
+
+function openRestore(event) {
+  if (!selectedBackup || readingBackup || restoringBackup || restoreBlocked || anyDialogOpen()) return;
+  restoreOpener = event.currentTarget;
+  restoreForm.reset();
+  element('restore-error').hidden = true;
+  element('restore-error').textContent = '';
+  element('restore-status').textContent = '';
+  element('restore-filename').textContent = selectedBackup.name;
+  for (const key of ['items', 'tasks', 'history']) element(`restore-${key}-count`).textContent = String(selectedBackup.counts[key]);
+  updateBackupControls();
+  restoreDialog.showModal();
+  restoreDialog.scrollTop = 0;
+  element('cancel-restore').focus();
+  element('cancel-restore').scrollIntoView({ block: 'nearest' });
+}
+
+function closeRestore() {
+  if (!restoringBackup && restoreDialog.open) restoreDialog.close();
+}
+
+function discardReplacedArchive() {
+  // Removed cards must never offer writes against the previous archive, even
+  // if the reads after a confirmed restore fail or an earlier read arrives late.
+  invalidateListLoad();
+  invalidateMaintenanceLoad();
+  invalidateTaskItemsLoad();
+  items = [];
+  loadedQuery = null;
+  searchInput.value = '';
+  needsMutationRefresh = true;
+  for (const key of fieldNames) newItemDraft[key] = '';
+  Object.assign(taskDraft, { title: '', itemId: '', dueDate: '', intervalDays: '0', notes: '' });
+  completionDrafts.clear();
+  completionIssues.clear();
+  editingItem = deletionItem = initialFormValues = null;
+  editingTask = deletionTask = completionTask = initialTaskFormValues = null;
+  taskItems = [];
+  taskItemsReady = false;
+  taskSelectedItemId = '';
+  taskEditBlocked = taskDeleteBlocked = false;
+  form.reset();
+  taskForm.reset();
+  completionForm.reset();
+  showSelectedTaskItem();
+  for (const id of ['item-list', 'task-list', 'history-list']) {
+    element(id).replaceChildren();
+    element(id).hidden = true;
+  }
+  const message = 'Ripristino completato. Oggetti, interventi e storico sono stati sostituiti. Le bozze precedenti sono state scartate.';
+  element('backup-feedback').textContent = message;
+  element('feedback').textContent = message;
+  element('task-feedback').textContent = message;
+  taskMutationConfirmed = 'Il ripristino è stato confermato dal server. Non ripetere la sostituzione.';
+  void loadItems();
+  void loadMaintenance();
+}
+
+element('backup-tab').addEventListener('click', () => showView('backup'));
+element('download-backup').addEventListener('click', downloadBackup);
+backupFile.addEventListener('change', readBackupFile);
+element('clear-backup-file').addEventListener('click', () => {
+  clearBackupSelection();
+  backupFile.focus();
+});
+element('restore-backup').addEventListener('click', openRestore);
+element('restore-consent').addEventListener('change', updateBackupControls);
+element('cancel-restore').addEventListener('click', closeRestore);
+element('close-restore').addEventListener('click', closeRestore);
+restoreDialog.addEventListener('cancel', event => {
+  if (restoringBackup) event.preventDefault();
+});
+restoreDialog.addEventListener('close', () => {
+  if (restoreDialog.open) return;
+  restoreForm.reset();
+  updateBackupControls();
+  if (restoreBlocked) {
+    element('backup-file-error').textContent = element('restore-error').textContent;
+    element('backup-file-error').hidden = false;
+  }
+  if (currentView === 'backup' && !anyDialogOpen()) {
+    const visible = restoreOpener.isConnected && !restoreOpener.disabled && restoreOpener.getClientRects().length;
+    (visible ? restoreOpener : backupTitle).focus();
+  }
+});
+restoreForm.addEventListener('submit', async event => {
+  event.preventDefault();
+  if (restoringBackup || restoreBlocked || !restoreDialog.open || !selectedBackup || !element('restore-consent').checked) return;
+  restoringBackup = true;
+  updateBackupControls();
+  element('restore-status').textContent = 'Sostituzione dell’archivio in corso. Attendi la conferma.';
+  element('restore-status').focus();
+  let confirmed = false;
+  try {
+    const result = await requestJSON('/api/restore', {
+      method: 'POST', headers: { 'Content-Type': 'application/json' },
+      body: selectedBackup.body, signal: AbortSignal.timeout(10000),
+    });
+    if (result?.ok !== true) throw new Error('Risposta al ripristino inattesa.');
+    confirmed = true;
+  } catch (error) {
+    const rejected = error instanceof ApiError && [400, 413, 415].includes(error.status);
+    const message = rejected
+      ? `Ripristino rifiutato: ${error.message} L’archivio non è stato sostituito. Annulla, rimuovi il file e scegli una copia valida.`
+      : 'Esito del ripristino non confermato: l’archivio potrebbe essere già stato sostituito. Chiudi questa conferma, scarica il backup corrente e controlla Oggetti, scadenze e Storico prima di qualsiasi nuovo tentativo. Nessun reinvio automatico.';
+    restoreBlocked = true;
+    element('restore-error').textContent = message;
+    element('restore-error').hidden = false;
+  } finally {
+    restoringBackup = false;
+    element('restore-status').textContent = '';
+    updateBackupControls();
+  }
+  if (!confirmed) {
+    element('restore-error').focus();
+    return;
+  }
+  clearBackupSelection();
+  restoreOpener = backupTitle;
+  restoreDialog.close();
+  backupTitle.focus();
+  discardReplacedArchive();
+});
