+// truncation, generated IDs, timestamp replacement or dangling-link repairs.
+export function validateRestore(input) {
+  shape(input, ['backup', 'mode'], [], 'Richiesta');
+  if (input.mode !== 'replace') {
+    throw new HttpError(400, 'Il ripristino richiede mode: "replace" e sostituisce tutti i dati.');
+  }
