+  shape(backup, ['schemaVersion', 'items', 'tasks', 'history'], [], 'backup');
+  if (backup.schemaVersion !== 1) throw new HttpError(400, 'Versione del backup non supportata: è richiesta schemaVersion 1.');
+  for (const key of ['items', 'tasks', 'history']) {
+    if (!Array.isArray(backup[key])) throw new HttpError(400, `backup.${key} deve essere un array.`);
+  }
+
+  const items = backup.items.map((record, index) => {
+    const path = `backup.items[${index}]`;
+    shape(record, itemKeys, [], path);
+    const { id, name, category, location, notes, createdAt, updatedAt } = record;
+    validateItemFields({ name, category, location, notes });
+    timestamps(record, path);
+    return { id, name, category, location, notes, createdAt, updatedAt };
+  });
+  const tasks = backup.tasks.map((record, index) => {
+    const path = `backup.tasks[${index}]`;
+    shape(record, taskKeys, ['deleted'], path);
+    const { id, itemId, title, dueDate, intervalDays, notes, completed, createdAt, updatedAt } = record;
+    validateTaskFields({ itemId, title, dueDate, intervalDays, notes });
+    boolean(completed, `${path}.completed`);
