+    // Event titles have the same literal-text constraints as task titles,
+    // but are snapshots: they need not equal the current title or itemId.
+    validateTaskFields({ title }, { partial: true });
+    validateCivilDate(completedOn, `${path}.completedOn`);
+    return { id, taskId, itemId, title, completedOn };
+  });
