+  const itemIds = unique(items, 'backup.items');
+  const taskIds = unique(tasks, 'backup.tasks');
+  unique(history, 'backup.history');
+  for (const [index, task] of tasks.entries()) {
+    reference(task.itemId, itemIds, `backup.tasks[${index}].itemId`);
+  }
+  for (const [index, event] of history.entries()) {
+    reference(event.taskId, taskIds, `backup.history[${index}].taskId`);
+    reference(event.itemId, itemIds, `backup.history[${index}].itemId`);
+  }
+  return { schemaVersion: 1, items, tasks, history };
